package main

import (
   "fmt"
   "net/http"
   "io/ioutil"
)

func main() {

   url := "%7B%7BbaseUrl%7D%7D/accounting/get-account-balance/%3Cstring%3E/?date=%3Cdate%3E&period=%3Cstring%3E"
   method := "GET"

   client := &http.Client {
   }
   req, err := http.NewRequest(method, url, nil)

   if err != nil {
      fmt.Println(err)
      return
   }
   req.Header.Add("Accept", "application/json")

   res, err := client.Do(req)
   if err != nil {
      fmt.Println(err)
      return
   }
   defer res.Body.Close()

   body, err := ioutil.ReadAll(res.Body)
   if err != nil {
      fmt.Println(err)
      return
   }
   fmt.Println(string(body))
}

