package main

import (
   "fmt"
   "strings"
   "net/http"
   "io/ioutil"
)

func main() {

   url := "%7B%7BbaseUrl%7D%7D/accounting/manual-accounting-policy/"
   method := "POST"

   payload := strings.NewReader(`{
  "record_date": "<date>",
  "description": "<string>",
  "accounting_records": {
    "account_code": "<string>",
    "debit": "<number>",
    "credit": "<number>"
  }
}`)

   client := &http.Client {
   }
   req, err := http.NewRequest(method, url, payload)

   if err != nil {
      fmt.Println(err)
      return
   }
   req.Header.Add("Content-Type", "application/json")
   req.Header.Add("Accept", "application/json")

   res, err := client.Do(req)
   if err != nil {
      fmt.Println(err)
      return
   }
   defer res.Body.Close()

   body, err := ioutil.ReadAll(res.Body)
   if err != nil {
      fmt.Println(err)
      return
